M1P1 = [
    q(AB, ATOM, 1, "Which particle in an atom has no electrical charge?", ["Proton", "Neutron", "Electron", "Ion"], "B",
      "Neutrons have no charge. Protons are positive and electrons are negative. Protons and neutrons are found in the nucleus."),
    q(AB, ATOM, 2, "An atom of fluorine has a mass number of 19 and an atomic number of 9. How many neutrons does it have?", ["9", "19", "28", "10"], "D",
      "Number of neutrons = mass number − atomic number = 19 − 9 = 10.",
      check=lambda: 19 - 9 == 10),
    q(AB, PT, 1, "Where are the metals found in the periodic table?",
      ["On the left and towards the bottom", "On the far right only", "Only in Group 0", "Only along the top row"], "A",
      "Metals are on the left and towards the bottom of the periodic table. Non-metals are on the right and towards the top."),
    q(AB, PT, 2, "What happens to the reactivity of the halogens going down Group 7?",
      ["It increases", "It stays the same", "It decreases", "It increases and then decreases"], "C",
      "The halogens become less reactive going down the group. Fluorine is the most reactive halogen. This is the opposite of the trend in Group 1."),
    q(AB, BOND, 1, "Ionic bonding happens between which types of element?",
      ["Two non-metals", "A metal and a non-metal", "Two metals", "Two noble gases"], "B",
      "In ionic bonding, metal atoms lose electrons to form positive ions and non-metal atoms gain electrons to form negative ions. The oppositely charged ions attract strongly."),
    q(AB, BOND, 2, r"Magnesium forms $\text{Mg}^{2+}$ ions and chlorine forms $\text{Cl}^-$ ions. What is the formula of magnesium chloride?",
      [r"$\text{MgCl}_2$", r"$\text{MgCl}$", r"$\text{Mg}_2\text{Cl}$", r"$\text{Mg}_2\text{Cl}_3$"], "A",
      r"The charges must balance. One $\text{Mg}^{2+}$ ion needs two $\text{Cl}^-$ ions, so the formula is $\text{MgCl}_2$."),
    q(QR, QUANT, 2, r"What is the relative formula mass of magnesium hydroxide, $\text{Mg(OH)}_2$? (Relative atomic masses: Mg = 24, O = 16, H = 1)",
      ["41", "42", "57", "58"], "D",
      r"The bracket means two OH groups. $M_r = 24 + 2 \times (16 + 1) = 24 + 34 = 58$.",
      check=lambda: AR["Mg"] + 2 * (AR["O"] + AR["H"]) == 58),
    q(QR, QUANT, 2, "Magnesium ribbon is heated in a crucible with a lid lifted now and then. The mass of the solid increases. Why?",
      ["Magnesium gets heavier when it is hot", "Mass is created in the reaction", "Oxygen atoms from the air join with the magnesium", "Water evaporates from the crucible"], "C",
      "Magnesium reacts with oxygen from the air to form magnesium oxide. The mass of the oxygen is added to the solid, so the mass goes up. Mass is still conserved overall."),
    q(QR, CHANGE, 2, "What is formed when an acid reacts with an alkali?",
      ["A salt and water", "A salt and hydrogen", "Carbon dioxide and water", "Only water"], "A",
      "This is neutralisation: acid + alkali → salt + water. Hydrogen ions from the acid react with hydroxide ions from the alkali to make water."),
    q(QR, CHANGE, 2, "How is iron extracted from iron oxide?",
      ["By electrolysis of the oxide", "By heating the oxide with carbon", "By dissolving the oxide in water", "By filtering the ore"], "B",
      "Iron is less reactive than carbon, so carbon can remove the oxygen from iron oxide. The iron oxide is reduced and the carbon is oxidised."),
    q(QR, ELEC, 2, "During electrolysis, to which electrode do positive ions move?",
      ["The positive electrode (anode)", "Both electrodes equally", "The negative electrode (cathode)", "Neither electrode"], "C",
      "Opposite charges attract, so positive ions move to the negative electrode and negative ions move to the positive electrode."),
    q(QR, ENERGY, 2, "During a reaction the temperature of the surrounding solution falls. What type of reaction is this?",
      ["Exothermic", "Neutralisation", "Combustion", "Endothermic"], "D",
      "An endothermic reaction takes in energy from its surroundings, so the temperature of the surroundings falls. Sports injury cold packs use endothermic reactions."),
]

M1P2 = [
    q(RO, RATE, 1, "Which change would decrease the rate of a reaction?",
      ["Adding a catalyst", "Using a powder instead of lumps", "Lowering the temperature", "Increasing the concentration of a solution"], "C",
      "At a lower temperature particles move more slowly, so they collide less often and with less energy. All the other changes increase the rate."),
    q(RO, RATE, 2, "Which symbol in an equation shows that a reaction is reversible?",
      [r"$\rightleftharpoons$", r"$\rightarrow$", r"$+$", r"$=$"], "A",
      r"The double half-arrow symbol $\rightleftharpoons$ shows that the reaction can go both forwards and backwards."),
    q(RO, RATE, 2, "Blue hydrated copper sulfate is heated and turns into white anhydrous copper sulfate. What happens when water is added to the white solid?",
      ["Nothing happens", "It turns black", "It turns blue again and takes in energy", "It turns blue again and gives out energy"], "D",
      "The reaction is reversible. If one direction is endothermic, the reverse is exothermic by the same amount. Heating took energy in, so adding water turns it blue again and releases energy."),
    q(RO, ORGANIC, 1, "What is the formula of methane, the simplest alkane?",
      [r"$\text{CH}_3$", r"$\text{CH}_4$", r"$\text{C}_2\text{H}_6$", r"$\text{CO}_2$"], "B",
      r"Methane has one carbon atom bonded to four hydrogen atoms: $\text{CH}_4$. It is the main gas in natural gas."),
    q(RO, ORGANIC, 2, "What are the products of the complete combustion of a hydrocarbon?",
      ["Carbon dioxide and water", "Carbon monoxide and water", "Carbon and hydrogen", "Oxygen and water"], "A",
      "When a hydrocarbon burns in plenty of oxygen, the carbon is oxidised to carbon dioxide and the hydrogen to water. Carbon monoxide and soot form when there is too little oxygen."),
    q(RO, ORGANIC, 2, "Alkenes are described as unsaturated. What does this mean?",
      ["They contain only single bonds", "They are dissolved in water", "They contain a carbon-carbon double bond", "They contain oxygen atoms"], "C",
      "Alkenes contain a C=C double bond, so they have two fewer hydrogen atoms than the alkane with the same number of carbons. Alkanes are saturated."),
    q(AE, ANAL, 1, "What is the test for hydrogen gas?",
      ["It relights a glowing splint", "A lighted splint burns with a squeaky pop", "It turns limewater milky", "It bleaches damp litmus paper"], "B",
      "A lighted splint held near hydrogen burns with a squeaky pop. A glowing splint relighting is the test for oxygen."),
    q(AE, ANAL, 2, "In paper chromatography, what does a pure substance produce?",
      ["Several spots", "No spots at all", "A line across the whole paper", "A single spot"], "D",
      "A pure substance contains only one compound, so it gives one spot in every solvent. A mixture separates into two or more spots."),
    q(AE, ATMOS, 2, "Which human activity increases the amount of methane in the atmosphere?",
      ["Planting trees", "Using wind turbines", "Raising cattle", "Recycling glass"], "C",
      "Cattle produce methane as they digest food. Rice paddy fields and rotting waste in landfill sites also release methane, a greenhouse gas."),
    q(AE, ATMOS, 2, "Which of these gases is NOT a greenhouse gas?", ["Nitrogen", "Carbon dioxide", "Methane", "Water vapour"], "A",
      "Carbon dioxide, methane and water vapour all absorb infrared radiation, so they are greenhouse gases. Nitrogen does not, even though it makes up most of the air."),
    q(AE, RES, 2, "Why is recycling aluminium cans better than extracting new aluminium from its ore?",
      ["Recycled aluminium is a different element", "It produces more waste", "It needs more electricity",
       "It uses much less energy and conserves the finite ore"], "D",
      "Extracting aluminium by electrolysis uses a lot of electricity. Recycling uses a small fraction of that energy, reduces mining and waste, and saves the limited ore."),
    q(AE, RES, 2, "Which three elements do NPK fertilisers provide?",
      ["Nickel, phosphorus and krypton", "Nitrogen, phosphorus and potassium", "Neon, phosphorus and potassium", "Nitrogen, platinum and potassium"], "B",
      "N, P and K are the chemical symbols for nitrogen, phosphorus and potassium, the three elements plants need most for healthy growth."),
]

