# ───────────────────────────────────────────────────────────────── practice paper 2
M2P1 = [
    q(AB, ATOM, 3, "Why do different isotopes of an element have the same chemical properties?",
      ["They have the same number of electrons, arranged in the same way", "They have the same number of neutrons",
       "They have the same mass number", "They have no electrons in their outer shell"], "A",
      "Chemical reactions depend on electrons. Isotopes have the same number of protons and so the same number and arrangement of electrons. Only their masses differ."),
    q(AB, ATOM, 2, "A particle has 12 protons, 12 neutrons and 10 electrons. Which particle is it? (Magnesium has atomic number 12.)",
      ["A neon atom", r"A $\text{Na}^+$ ion", r"A $\text{Mg}^{2+}$ ion", r"A $\text{Mg}^{2-}$ ion"], "C",
      r"12 protons means it is magnesium. It has two more protons than electrons, so its charge is $2+$. It is a $\text{Mg}^{2+}$ ion.",
      check=lambda: 12 - 10 == 2),
    q(AB, PT, 3, "Why does the reactivity of the halogens decrease going down Group 7?",
      ["The atoms lose electrons more easily", "The outer shell is further from the nucleus, so an electron is gained less easily",
       "The atoms have more electrons in their outer shell", "The molecules become lighter"], "B",
      "Halogens react by gaining one electron. Further down the group there are more shells, so the outer shell is further from the nucleus and more shielded. The attraction for an extra electron is weaker."),
    q(AB, PT, 2, "Which property is typical of transition metals but not of Group 1 metals?",
      ["Low density", "Low melting point", "Vigorous reaction with cold water", "Forming coloured compounds and acting as catalysts"], "D",
      "Transition metals such as iron and copper are dense, have high melting points, form ions with different charges and coloured compounds, and are useful catalysts. Group 1 metals are soft, low-density and very reactive."),
    q(AB, BOND, 3, "Why does sodium chloride conduct electricity when molten but not when solid?",
      ["Electrons are only free when it is molten", "Sodium chloride molecules break apart when molten",
       "When molten its ions are free to move and carry charge", "Solid sodium chloride has no ions"], "C",
      "In the solid the ions are held in fixed positions in the lattice. When it melts or dissolves, the ions can move and carry charge through the liquid."),
    q(AB, BOND, 3, "Why are nanoparticles often very effective catalysts?",
      ["They have a very high surface area to volume ratio", "They are heavier than normal particles", "They contain no atoms", "They react with everything"], "A",
      "Nanoparticles are 1 to 100 nm across, so a large share of their atoms are at the surface. This very high surface area to volume ratio means smaller amounts are needed to catalyse a reaction."),
    q(QR, QUANT, 3, r"0.2 mol of sodium hydroxide is dissolved in water to make $250\ \text{cm}^3$ of solution. What is its concentration?",
      [r"$0.05\ \text{mol/dm}^3$", r"$0.8\ \text{mol/dm}^3$", r"$50\ \text{mol/dm}^3$", r"$1.25\ \text{mol/dm}^3$"], "B",
      r"Convert the volume: $250\ \text{cm}^3 = 0.25\ \text{dm}^3$. Concentration $= \dfrac{0.2}{0.25} = 0.8\ \text{mol/dm}^3$.",
      check=lambda: near(0.2 / (250 / 1000), 0.8)),
    q(QR, QUANT, 3, r"At room temperature and pressure, one mole of any gas occupies $24\ \text{dm}^3$. What volume does 0.5 mol of carbon dioxide occupy?",
      [r"$48\ \text{dm}^3$", r"$24.5\ \text{dm}^3$", r"$0.021\ \text{dm}^3$", r"$12\ \text{dm}^3$"], "D",
      r"Volume $=$ moles $\times 24 = 0.5 \times 24 = 12\ \text{dm}^3$.",
      check=lambda: 0.5 * 24 == 12),
    q(QR, CHANGE, 3, "Why is ethanoic acid described as a weak acid?",
      ["It only partially ionises in water", "It has a low concentration", "It does not contain hydrogen", "It has a pH above 7"], "A",
      "A weak acid only partly ionises into hydrogen ions in solution, while a strong acid such as hydrochloric acid ionises completely. 'Weak' is not the same as 'dilute', which describes a low concentration."),
    q(QR, CHANGE, 3, r"The pH of a solution decreases by 1. What happens to the concentration of $\text{H}^+$ ions?",
      ["It halves", "It doubles", "It decreases by a factor of 10", "It increases by a factor of 10"], "D",
      r"Each decrease of one pH unit means the hydrogen ion concentration is 10 times greater. A fall of 2 units would mean $10 \times 10 = 100$ times greater."),
    q(QR, ELEC, 3, "In the extraction of aluminium, the aluminium oxide is dissolved in molten cryolite. Why?",
      ["Cryolite is a catalyst that speeds up the reaction", "Cryolite removes oxygen from the cell",
       "It lowers the operating temperature, saving energy and cost", "It makes the aluminium more reactive"], "C",
      "Aluminium oxide has a very high melting point. Dissolving it in molten cryolite means the cell can run at a much lower temperature, which saves energy. The carbon positive electrodes still need replacing because they react with oxygen."),
    q(QR, ENERGY, 3, "In an exothermic reaction, how does the energy released when new bonds form compare with the energy needed to break the bonds in the reactants?",
      ["It is less", "It is greater", "It is exactly the same", "No energy is involved in making bonds"], "B",
      "Breaking bonds takes in energy and making bonds releases energy. In an exothermic reaction more energy is released by making bonds than is taken in to break them, so there is an overall release of energy."),
]

M2P2 = [
    q(RO, RATE, 3, "A reversible reaction is at equilibrium in a closed system. More of one of the reactants is added. What happens?",
      ["The position of equilibrium shifts to the left", "The reaction stops", "Nothing changes",
       "The position of equilibrium shifts to the right, making more product"], "D",
      "By Le Chatelier's principle, the system responds to oppose the change. Adding reactant shifts the equilibrium to the right, using up some of the added reactant and making more product."),
    q(RO, RATE, 3, "How does a catalyst increase the rate of a reaction?",
      ["It increases the temperature", "It provides a different reaction pathway with a lower activation energy",
       "It gives the particles more energy", "It increases the concentration of the reactants"], "B",
      "A catalyst provides an alternative pathway with a lower activation energy. More of the collisions have enough energy to react, so the rate increases."),
    q(RO, RATE, 3, "A flask containing marble chips and acid loses 0.60 g of carbon dioxide in the first 2 minutes. What is the mean rate of reaction in g/s?",
      ["0.005 g/s", "0.3 g/s", "0.05 g/s", "200 g/s"], "A",
      r"Convert the time to seconds: 2 minutes = 120 s. Mean rate $= \dfrac{0.60}{120} = 0.005$ g/s.",
      check=lambda: near(0.60 / 120, 0.005)),
    q(RO, ORGANIC, 3, "Which statement describes the addition polymerisation of ethene?",
      ["Ethene molecules join and water is given off", "Ethene is broken into smaller molecules",
       "Many ethene molecules join together as their double bonds open, forming a single product", "Ethene reacts with oxygen to form a polymer"], "C",
      "In addition polymerisation the C=C double bond in each monomer opens, and many monomers join into a long chain. Poly(ethene) is the only product. Polymers that give off water are condensation polymers."),
    q(RO, ORGANIC, 3, "Ethanol reacts with ethanoic acid, with an acid catalyst. What is formed?",
      ["Ethene and water", "Ethane and oxygen", "Carbon dioxide and water", "Ethyl ethanoate, an ester, and water"], "D",
      "An alcohol and a carboxylic acid react to form an ester and water. Ethyl ethanoate is a sweet-smelling ester used in solvents and flavourings."),
    q(RO, ORGANIC, 2, "Compared with long-chain hydrocarbons, short-chain hydrocarbons are...",
      ["more flammable, less viscous and have lower boiling points", "less flammable, more viscous and have higher boiling points",
       "more viscous and have higher boiling points", "less flammable and have higher boiling points"], "A",
      "Short molecules have weaker forces between them, so they boil at lower temperatures, flow more easily and catch fire more easily. This makes them more useful as fuels."),
    q(AE, ANAL, 3, "What is one advantage of flame emission spectroscopy over a simple flame test?",
      ["It can only identify one metal at a time", "It does not need a sample", "It can identify metal ions in a mixture and measure their concentration",
       "It changes the colour of the flame"], "C",
      "Instrumental methods such as flame emission spectroscopy are sensitive, accurate and fast. The spectrum can identify ions even in mixtures, and its intensity shows the concentration. Flame tests struggle with mixtures."),
    q(AE, ANAL, 2, "Dilute hydrochloric acid and barium chloride solution are added to a solution. A white precipitate forms. Which ion is present?",
      ["Carbonate", "Sulfate", "Chloride", "Nitrate"], "B",
      "Sulfate ions form a white precipitate of barium sulfate with barium chloride. The acid is added first to remove carbonate ions, which would otherwise also give a precipitate."),
    q(AE, ATMOS, 3, "How did the amount of carbon dioxide in the Earth's early atmosphere decrease?",
      ["Volcanoes turned it into nitrogen", "It escaped into space", "Animals used it up by breathing",
       "It dissolved in the oceans, became locked in rocks and fossil fuels, and was used in photosynthesis"], "D",
      "Carbon dioxide dissolved in the oceans and formed carbonate precipitates and sedimentary rocks. Algae and plants took it in for photosynthesis, and some carbon became locked up in fossil fuels."),
    q(AE, ATMOS, 2, "What is the carbon footprint of a product?",
      ["The mass of carbon in the product", "The total amount of carbon dioxide and other greenhouse gases released over its full life cycle",
       "The area of land needed to make it", "The amount of carbon dioxide it absorbs"], "B",
      "A carbon footprint covers emissions from making, transporting, using and disposing of a product. It can be reduced by using renewable energy, improving efficiency and carbon capture."),
    q(AE, RES, 3, "In phytomining, how are metal compounds obtained from low-grade ores?",
      ["Plants are grown on the land, then harvested and burned, and the ash contains metal compounds", "Bacteria produce a solution of the metal from the ore",
       "The ore is heated with carbon in a blast furnace", "The ore is dissolved in seawater"], "A",
      "Plants absorb metal compounds from the soil. When the plants are burned, the ash is rich in metal compounds, which can be extracted by electrolysis or displacement. Using bacteria is bioleaching."),
    q(AE, RES, 3, "The forward reaction in the Haber process is exothermic. Why is a temperature of about 450 °C used?",
      ["A higher temperature would give a higher yield", "The iron catalyst melts above 450 °C",
       "A lower temperature would give a higher yield, but the rate would be too slow", "Ammonia breaks down below 450 °C"], "C",
      "Because the forward reaction is exothermic, a lower temperature would give a higher yield of ammonia. However, the reaction would be too slow, so 450 °C is a compromise between yield and rate."),
]

